                                                                                                                                                                                                           
  CREATE TABLE "JW_USER_GROUP"                                                                                                                                                              
   (	"USER_GROUP_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" VARCHAR2(100),                                                                                                                                                                               
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                     
	"UPDATED_BY" VARCHAR2(100),                                                                                                                                                                               
	"UPDATED_DATE" DATE DEFAULT sysdate,                                                                                                                                                                      
	"REMARK" VARCHAR2(512),                                                                                                                                                                                   
	"NAME" VARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                                      
	"DEL_FLAG" NUMBER DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                              
	"SCOPE_TYPE" VARCHAR2(15) DEFAULT 'ALL' NOT NULL ENABLE,                                                                                                                                                  
	 PRIMARY KEY ("USER_GROUP_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                      
   ) ;                                                                                                                                                                                                     

